    function documentEvidenceId(meta) {return meta&&typeof meta.evidenceId==='string'&&meta.evidenceId?meta.evidenceId:meta&&typeof meta.sourceDocumentId==='string'&&meta.sourceDocumentId?meta.sourceDocumentId:meta&&typeof meta.id==='string'&&meta.contactId&&meta.name&&meta.uploadedAt?meta.id:null;}
