          if(state.actor.id!==actorId||!getContact(c.id))throw new Error('El acceso al expediente cambió durante la carga.');
          if(!persisted||!persisted.blob||persisted.id!==meta.id||persisted.contactId!==c.id||persisted.actorId!==actorId||persisted.size!==meta.size||persisted.mimeType!==meta.mimeType||persisted.name!==meta.name||persisted.uploadedAt!==meta.uploadedAt||persisted.blob.size!==meta.size||persisted.blob.type!==meta.mimeType)throw new Error('No pudo verificarse el archivo local de este contacto.');
